export const protocolVersion = 1;

export function csvRow(values) {
  return values.map(cell => {
    const needsQuoting = (
      String(cell).includes(',') ||
      String(cell).includes('"') ||
      String(cell).includes('\r') ||
      String(cell).includes('\n')
    );

    if (!needsQuoting) {
      return String(cell);
    }

    const escaped = String(cell).replace(/"$/gm, '""');
    return `"${escaped}"`;
  }).join(',');
}

